292	    private func generateDaysInMonth() -> [Date?] {
293	        guard let monthInterval = calendar.dateInterval(of: .month, for: currentMonth),
294	              let monthFirstWeek = calendar.dateInterval(of: .weekOfMonth, for: monthInterval.start)
295	        else { return [] }
296	        var days: [Date?] = []
297	        var currentDate = monthFirstWeek.start
298	        let weekday = calendar.component(.weekday, from: currentDate)
299	        let daysToMonday = (weekday == 1) ? -6 : (2 - weekday)
300	        currentDate = calendar.date(byAdding: .day, value: daysToMonday, to: currentDate) ?? currentDate
301	        for _ in 0..<42 {
302	            days.append(currentDate)
303	            currentDate = calendar.date(byAdding: .day, value: 1, to: currentDate) ?? currentDate
304	        }
305	        return days
306	    }
