private func migrateOne(projectId: UUID, inventoryManager: InventoryManager) async -> MigrationOutcome {
    // Step 1+2: Fetch thumbnail, check displayThumbnail current state
    let thumbnailData: Data
    do {
        let descriptor = FetchDescriptor<SDProjectRecord>(
            predicate: #Predicate { $0.id == projectId }
        )
        guard let sd = try context.fetch(descriptor).first else {
            return .raceSkipped  // row 被删
        }
        guard let thumb = sd.thumbnail else {
            return .raceSkipped  // thumbnail 被清
        }
        if sd.displayThumbnail != nil {
            return .alreadyDone  // 已被并发填
        }
        thumbnailData = thumb
    } catch {
        AppLogger.shared.error("ThumbnailMigration", "fetch_failed", ...)
        return .failed
    }

    // Step 3: Downsample in detached Task (releases MainActor)
    let downsampled: Data? = await Task.detached(priority: .utility) {
        ImageDownsampler.downsample(thumbnailData)
    }.value
    guard !Task.isCancelled else { return .cancelled }
    guard let downsampled else {
        AppLogger.shared.error("ThumbnailMigration", "downsample_failed", ...)
        return .failed
    }

    // Step 4: TOCTOU revalidation
    let currentThumb: Data
    do {
        let descriptor = FetchDescriptor<SDProjectRecord>(
            predicate: #Predicate { $0.id == projectId }
        )
        guard let sd = try context.fetch(descriptor).first else {
            return .raceSkipped
        }
        guard let thumb = sd.thumbnail else {
            return .raceSkipped
        }
        if sd.displayThumbnail != nil {
            return .alreadyDone
        }
        currentThumb = thumb
    } catch {
        AppLogger.shared.error("ThumbnailMigration", "revalidate_fetch_failed", ...)
        return .failed
    }
    if currentThumb != thumbnailData {
        AppLogger.shared.info("ThumbnailMigration", "race_thumbnail_changed_skip", ...)
        return .raceSkipped
    }

    // Step 5: Write back via InventoryManager.setProjectDisplayThumbnail
    let ok = inventoryManager.setProjectDisplayThumbnail(projectId: projectId, displayThumbnail: downsampled)
    if ok {
        AppLogger.shared.info("ThumbnailMigration", "migrated_one", ...)
        return .migrated
    } else {
        return .failed
    }
}
```

