// MARK: - 成品图缩略磁盘缓存

/// 成品图缩略图的**磁盘缓存** —— 派生、可丢弃的性能缓存，故意放 `Library/Caches/`：
/// 不进 iCloud / 备份、系统存储紧张时可被清掉，丢了下次看时自动重算。所以它**不该**进
/// SwiftData（那会被 CloudKit 同步、撑大备份，等于拿同步配额存一个随时能重算的东西）。
///
/// 用法（见 `ProjectFinishedThumbnail`）：日历格子先 `load`，命中就直接用这份 ~KB 小图、
/// 跳过整张原图 PNG 的取数+解码；未命中才走原图降级（`ImageDownsampler` + 限流闸门），
/// 然后 `store` 写回，下次即快。老用户的图就在翻看日历的过程中自己缓存好 —— 不需要后台迁移协调器。
///
/// **缓存键 = projectId**（只缓存当前这一种日历显示尺寸）。若以后要在多种尺寸下复用该组件，
/// 需把尺寸并入文件名 + `invalidate` 按前缀删。当前单一尺寸，保持最简。
///
/// 失效挂在「改成品图 / 删项目」（`invalidate`）和「恢复备份」（`clearAll`）这些主路径上；
/// 极少见的「undo 换成品图且未走 setter」可能短暂显示旧小图 —— 纯视觉、下次一存即自愈。
enum FinishedThumbnailCache {
    private static let dirName = "FinishedThumbnails"

    /// `Caches/FinishedThumbnails/`，懒创建。取不到 caches 目录时返回 nil（缓存整体降级为"永不命中"）。
    private static func directory() -> URL? {
        guard let caches = FileManager.default.urls(for: .cachesDirectory, in: .userDomainMask).first else {
            return nil
        }
        let dir = caches.appendingPathComponent(dirName, isDirectory: true)
        if !FileManager.default.fileExists(atPath: dir.path) {
            try? FileManager.default.createDirectory(at: dir, withIntermediateDirectories: true)
        }
        return dir
    }

    private static func fileURL(for projectId: UUID) -> URL? {
        directory()?.appendingPathComponent("\(projectId.uuidString).jpg")
    }

    /// 命中返回已解码小图；未命中 / 读失败返回 nil（调用方据此走原图降级）。
    static func load(_ projectId: UUID) -> UIImage? {
        guard let url = fileURL(for: projectId),
              let data = try? Data(contentsOf: url) else { return nil }
        return UIImage(data: data)
    }

    /// 写回缓存（JPEG ~KB）。尽力而为，失败静默 —— 丢了下次重算，不影响正确性。
    static func store(_ image: UIImage, for projectId: UUID) {
        guard let url = fileURL(for: projectId),
              let data = image.jpegData(compressionQuality: 0.8) else { return }
        try? data.write(to: url, options: .atomic)
    }

    /// 单个失效：成品图被改 / 项目被删时调，避免下次读到旧图。
    static func invalidate(_ projectId: UUID) {
        guard let url = fileURL(for: projectId) else { return }
        try? FileManager.default.removeItem(at: url)
    }

    /// 整目录清空：恢复备份后调 —— 项目 id 不变但图可能整体被换，逐个失效不可靠，直接全清重算。
    static func clearAll() {
        guard let caches = FileManager.default.urls(for: .cachesDirectory, in: .userDomainMask).first else { return }
        try? FileManager.default.removeItem(at: caches.appendingPathComponent(dirName, isDirectory: true))
    }
}

