//
//  FinishedThumbnailCacheTests.swift
//  BeadInventoryTests
//
//  成品图缩略磁盘缓存的读写/失效/清空往返验证。
//

import XCTest
import UIKit
@testable import BeadInventory

final class FinishedThumbnailCacheTests: XCTestCase {

    private func makeImage(_ side: CGFloat = 32) -> UIImage {
        let size = CGSize(width: side, height: side)
        return UIGraphicsImageRenderer(size: size).image { ctx in
            UIColor.systemTeal.setFill()
            ctx.fill(CGRect(origin: .zero, size: size))
        }
    }

    override func tearDown() {
        FinishedThumbnailCache.clearAll()   // 测试间互不污染
        super.tearDown()
    }

    func testStoreThenLoadRoundTrips() {
        let id = UUID()
        XCTAssertNil(FinishedThumbnailCache.load(id), "未写入前应未命中")
        FinishedThumbnailCache.store(makeImage(), for: id)
        let loaded = FinishedThumbnailCache.load(id)
        XCTAssertNotNil(loaded, "写入后应命中")
        XCTAssertEqual(loaded?.size.width ?? 0, 32, accuracy: 1)
        XCTAssertEqual(loaded?.size.height ?? 0, 32, accuracy: 1)
    }

    func testInvalidateRemovesEntry() {
        let id = UUID()
        FinishedThumbnailCache.store(makeImage(), for: id)
        XCTAssertNotNil(FinishedThumbnailCache.load(id))
        FinishedThumbnailCache.invalidate(id)
        XCTAssertNil(FinishedThumbnailCache.load(id), "失效后应未命中")
    }

    func testInvalidateIsScopedToOneProject() {
        let a = UUID(), b = UUID()
        FinishedThumbnailCache.store(makeImage(), for: a)
        FinishedThumbnailCache.store(makeImage(), for: b)
        FinishedThumbnailCache.invalidate(a)
        XCTAssertNil(FinishedThumbnailCache.load(a))
        XCTAssertNotNil(FinishedThumbnailCache.load(b), "失效 a 不应影响 b")
    }

    func testClearAllRemovesEverything() {
        let a = UUID(), b = UUID()
        FinishedThumbnailCache.store(makeImage(), for: a)
        FinishedThumbnailCache.store(makeImage(), for: b)
        FinishedThumbnailCache.clearAll()
        XCTAssertNil(FinishedThumbnailCache.load(a))
        XCTAssertNil(FinishedThumbnailCache.load(b))
    }
}

